struct Tape {
private:
    struct Node {
        double v = 0.0;
        double adj = 0.0;
        int op = 0;          // 0 = leaf, 1 = add, 2 = mul, 3 = sin, 4 = exp
        int a = -1, b = -1;  // operand ids
        bool wants_grad = false;
    };
    std::vector<Node> n;

    static bool needs_adj(const Node& x) {
        return x.op != 0 || x.wants_grad;
    }

public:
    int constant(double v) {
        n.push_back(Node{});
        n.back().v = v;
        return (int)n.size() - 1;
    }

    int input(double v) {
        n.push_back(Node{});
        n.back().v = v;
        n.back().wants_grad = true;
        return (int)n.size() - 1;
    }

    int add(int a, int b) {
        n.push_back(Node{});
        Node& x = n.back();
        x.v = n[a].v + n[b].v;
        x.op = 1;
        x.a = a;
        x.b = b;
        return (int)n.size() - 1;
    }

    int mul(int a, int b) {
        n.push_back(Node{});
        Node& x = n.back();
        x.v = n[a].v * n[b].v;
        x.op = 2;
        x.a = a;
        x.b = b;
        return (int)n.size() - 1;
    }

    int sin_(int a) {
        n.push_back(Node{});
        Node& x = n.back();
        x.v = std::sin(n[a].v);
        x.op = 3;
        x.a = a;
        return (int)n.size() - 1;
    }

    int exp_(int a) {
        n.push_back(Node{});
        Node& x = n.back();
        x.v = std::exp(n[a].v);
        x.op = 4;
        x.a = a;
        return (int)n.size() - 1;
    }

    double value(int node) const {
        return n[node].v;
    }

    void backward(int root) {
        for (Node& x : n) x.adj = 0.0;
        n[root].adj = 1.0;
        // Reverse recording order: every consumer of node i has a higher id,
        // so it is processed (and has finished accumulating into i) first.
        for (int i = (int)n.size() - 1; i >= 0; --i) {
            const Node& x = n[i];
            if (x.op == 0) continue;
            const double g = x.adj;
            if (g == 0.0) continue;
            switch (x.op) {
                case 1:
                    if (needs_adj(n[x.a])) n[x.a].adj += g;
                    if (needs_adj(n[x.b])) n[x.b].adj += g;
                    break;
                case 2:
                    if (needs_adj(n[x.a])) n[x.a].adj += g * n[x.b].v;
                    if (needs_adj(n[x.b])) n[x.b].adj += g * n[x.a].v;
                    break;
                case 3:
                    if (needs_adj(n[x.a])) n[x.a].adj += g * std::cos(n[x.a].v);
                    break;
                case 4:
                    if (needs_adj(n[x.a])) n[x.a].adj += g * x.v;  // dexp/dx = exp(x)
                    break;
            }
        }
    }

    double grad(int node) const {
        return n[node].adj;
    }
};
